    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn emit_call_boxed_variant<H: EmitHost>(&self, world: &EmitWorld<'_, '_, '_, '_>, walk: &mut EmitWalk, out: &mut EmitOut, host: &H, func: &Expr, args: &[Expr], depth: i64, flow: EmitFlow, scope: &EmitScope) -> Result<bool, Box<dyn std::error::Error>> {
        Ok(match func {
            Expr::Path(segments, _) => {
                if segments.len() < 2 { return Ok(false); }
                let owner = emit_text(world, *nikaia_std::index::get(&segments, nikaia_std::index::at(segments.len() as i64 - 2)));
                let variant = emit_text(world, *nikaia_std::index::get(&segments, nikaia_std::index::at(segments.len() as i64 - 1)));
                let mut mask: Vec<bool> = vec![];
                let mut any = false;
                for at in 0..args.len() as i64 {
                    let boxed = self.is_boxed(&owner, &boxed_member(&variant, at, ""));
                    mask.push(boxed);
                    if boxed { any = true; }
                }
                let mut holds_a_hull = false;
                if self.is_variant(world, &owner, &variant) { for arg in args.iter() { if emit_call_builds_a_hull(world, arg) { holds_a_hull = true; } } }
                if !any && !holds_a_hull { return Ok(false); }
                walk.boxed_args = Some(mask);
                let mut counts: Vec<Count> = vec![];
                for at in 0..args.len() as i64 { counts.push(self.count_at(host.crossings_are_possible(), "<field>", &variant_slot(&owner, &variant, at))); }
                walk.variant_counts = Some(counts);
                let mut names: Vec<String> = vec![];
                for s in segments.iter() {
                    let s = *s;
                    names.push(emit_text(world, s));
                }
                out.push(&self.path(world, walk.trusting, false, &names));
                out.push("(");
                self.emit_core_args(world, walk, out, host, &variant, args, &vec![], depth, flow, scope)?;
                walk.boxed_args = None;
                walk.variant_counts = None;
                out.push(")");
                return Ok(true);
            },
            _ => return Ok(false),
        })
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    #[allow(clippy::too_many_arguments)]
    pub fn emit_core_method_call<H: EmitHost>(&self, world: &EmitWorld<'_, '_, '_, '_>, walk: &mut EmitWalk, out: &mut EmitOut, host: &H, receiver: Option<&Expr>, on_node: i64, method: winnow_grammar::Symbol, args: &[Expr], config: &[ConfigArg], depth: i64, flow: EmitFlow, scope: &EmitScope) -> Result<(), Box<dyn std::error::Error>> {
        let hoisted = self.emit_method_hoisted(world, receiver, args);
        if hoisted.is_empty() {
            walk.hoisted_args = None;
            self.emit_core_method_call_body(world, walk, out, host, receiver, on_node, method, args, config, depth, flow, scope)?;
            return Ok(());
        }
        let mut inner = EmitOut::empty();
        walk.hoisted_args = Some(hoisted);
        walk.hoisted_lets = None;
        self.emit_core_method_call_body(world, walk, &mut inner, host, receiver, on_node, method, args, config, depth, flow, scope)?;
        walk.hoisted_args = None;
        let lets: EmitOut = nikaia_std::index::or(match walk.hoisted_lets.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || EmitOut::empty());
        walk.hoisted_lets = None;
        if lets.buf == "" {
            out.append(inner);
            return Ok(());
        }
        out.push("({ ");
        out.append(lets);
        out.append(inner);
        out.push(" })");
        Ok(())
    }
    pub(crate) fn emit_method_hoisted(&self, world: &EmitWorld<'_, '_, '_, '_>, receiver: Option<&Expr>, args: &[Expr]) -> Vec<i64> {
        let on = match receiver { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
        if !emit_pure_place(on) { return vec![]; }
        let mut last = -1;
        let root = root_of(world.words, on);
        if root.is_some() {
            let name = nikaia_std::index::or(root, || "".into());
            let mut j = 0;
            for later in args.iter() {
                if made_in_the_call(later) && !emit_arg_is_closure(later) && self.emit_lends_mut(world, later, &name) { last = j; }
                j += 1;
            }
        }
        let mut i = 0;
        for arg in args.iter() {
            if self.facts.mut_args.contains(&node_key(arg)) {
                let lent_root = root_of(world.words, arg);
                if lent_root.is_some() {
                    let lent_name = nikaia_std::index::or(lent_root, || "".into());
                    let mut j = 0;
                    for later in args.iter() {
                        if j > i && j > last && made_in_the_call(later) && !emit_arg_is_closure(later) && emit_mentions(world, later, &lent_name) { last = j; }
                        j += 1;
                    }
                }
            }
            i += 1;
        }
        let mut hoisted: Vec<i64> = vec![];
        let mut k = 0;
        for arg in args.iter() {
            if k <= last && made_in_the_call(arg) && !emit_arg_is_closure(arg) && !self.facts.mut_args.contains(&node_key(arg)) { hoisted.push(k); }
            k += 1;
        }
        hoisted
    }
    pub(crate) fn emit_lends_mut(&self, world: &EmitWorld<'_, '_, '_, '_>, expr: &Expr, name: &str) -> bool {
        for each in visited_in_expr(expr) {
            let lent = self.facts.mut_args.contains(&node_key(each)) || self.facts.mut_receivers.contains(&node_key(each));
            if lent && nikaia_std::index::or(root_of(world.words, each), || "".into()) == name { return true; }
        }
        false
    }
